// The most references of each kind a def holds, which bound its names:
// set in file_fields.h to these sums of the caps.
static_assert(MVFX_FILE_MAX_GRIDS == MVFX_MAX_EMITTERS * MVFX_MAX_FORCES +
                                         MVFX_MAX_EMITTERS * MVFX_MAX_COLLIDERS +
                                         MVFX_MAX_GASES * MVFX_MAX_COLLIDERS +
                                         MVFX_MAX_GASES * MVFX_MAX_FORCES + MVFX_MAX_WATERS,
              "1092");
static_assert(MVFX_FILE_MAX_MESHES == MVFX_MAX_EMITTERS + MVFX_MAX_EMITTERS, "128");
static_assert(MVFX_FILE_MAX_MODULES == MVFX_MAX_EMITTERS * MVFX_MAX_HOST_MODULES, "512");
